#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

int main() {
	ll n, k;
	cin >> n >> k;
	ll mod = 3 * n;
	ll M = (n - 1) / 2;
	ll inv2 = (mod + 1) / 2;
	ll x = (3 * M % mod) * inv2 % mod;
	vector<ll> a(n), b(n);
	a[0] = x;
	for (int i = 1; i < n; i++) {
		a[i] = (3 * (i - 1) - a[i-1]) % mod;
		if (a[i] < 0) a[i] += mod;
	}
	for (int i = 0; i < n; i++) {
		b[i] = (3 * i + 1 - a[i]) % mod;
		if (b[i] < 0) b[i] += mod;
	}
	for (int i = 0; i < n; i++) {
		if (a[i] > mod / 2) a[i] -= mod;
		if (b[i] > mod / 2) b[i] -= mod;
	}
	cout << "Yes\n";
	for (int i = 0; i < n; i++) {
		cout << a[i] << (i == n-1 ? '\n' : ' ');
	}
	for (int i = 0; i < n; i++) {
		cout << b[i] << (i == n-1 ? '\n' : ' ');
	}
	return 0;
}

