int n;
string s;

void insert(const string &str) {
	int now = 0;
	for(int i = 0; i < (int)str.size(); i++) {
		int x = str[i] - 'a';
		if(!ch[now][x]) ch[now][x] = ++tot;
		now = ch[now][x];
	}
	val[now]++;
}

void getFail() {
	queue<int> q;
	for(int i = 0; i < 26; i++) 
		if(ch[0][i]) q.push(ch[0][i]);

	while(!q.empty()) {
		int u = q.front(); q.pop();
		for(int i = 0; i < 26; i++) {
			if(ch[u][i]) {
				fail[ch[u][i]] = ch[fail[u]][i];
				q.push(ch[u][i]);
			} else {
				ch[u][i] = ch[fail[u]][i];
			}
		}
	}
}

int query(const string &text) {
	int now = 0, ans = 0;
	for(int i = 0; i < (int)text.size(); i++) {
		int x = text[i] - 'a';
		now = ch[now][x];
		for(int t = now; t && val[t] != -1; t = fail[t]) {
