	int l,r;
}ans[scx<<2];
int ans_cnt=0;

bool cmp(L a,L b){
	if(a.x!=b.x)return a.x<b.x;
	if(a.cr!=b.cr)return a.cr<b.cr;
	if(a.cr){
		return a.h<b.h;
	}else{
		return a.h>b.h;
	}
}

