#include <bits/stdc++.h>
using namespace std;

#define int long long
const int scx = 1e6 + 10;

int n, m;
int a[scx];

struct node {
	int l, r;
	int val;
	int tag;
} tree[scx << 2];

#define ls(u) (u << 1)
#define rs(u) ((u << 1) | 1)
#define mid(l, r) ((l + r) >> 1) 

void up(int u) {
	tree[u].val = tree[ls(u)].val + tree[rs(u)].val;
}
void bt(int u, int l, int r) {
	tree[u].l = l, tree[u].r = r;
	if (l == r) {
		tree[u].val = a[l];
		tree[u].tag = 0;
		return;
	}
	bt(ls(u), l, mid(l, r));
	bt(rs(u), mid(l, r) + 1, r);
	up(u);
}

void down(int u) {
	if (tree[u].tag > 0 || tree[u].tag < 0) {
		tree[ls(u)].tag += tree[u].tag;
		tree[rs(u)].tag += tree[u].tag;
		tree[ls(u)].val += (tree[ls(u)].r - tree[ls(u)].l + 1) * tree[u].tag;
		tree[rs(u)].val += (tree[rs(u)].r - tree[rs(u)].l + 1) * tree[u].tag;
		tree[u].tag = 0;
	}
}

void update(int u, int l, int r, int k) {
	if (tree[u].l > r || tree[u].r < l) {
		return;
	}
	else if (tree[u].l >= l && tree[u].r <= r) {
		tree[u].tag += k;
		tree[u].val += (tree[u].r - tree[u].l + 1) * k;
	}
	else {
		down(u);
		update(ls(u), l, r, k);
		update(rs(u), l, r, k);
		up(u);
	}
}

int qurey(int u, int l, int r) {
	if (tree[u].l > r || tree[u].r < l) {
		return 0;
	}
	else if (tree[u].l >= l && tree[u].r <= r) {
		return tree[u].val;
	}
	else {
		down(u);
		return qurey(ls(u), l, r) + qurey(rs(u), l, r);
	}
}

