		if (pos[x].first == 0) pos[x].first = i;
		else pos[x].second = i;
	}

	for (int i = 1; i <= tot; i++) a[i] = 1;

	bt(1, 1, tot);

	vector<pair<int, int>> v;
	for (int i = 1; i <= n; i++) {
		v.push_back({pos[i].first, pos[i].second});
	}
	sort(v.begin(), v.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
		return (a.second - a.first) < (b.second - b.first);
	});
	int swap_cnt = 0;
	for (auto [l, r] : v) {
		int remain = qurey(1, l, r);
		swap_cnt += (remain - 2);
