#include <bits/stdc++.h>
using namespace std;

const int scx = 4e5+10;

int n, m, k;
int fa[scx], rnk[scx];
bool dead[scx];
int q[scx];
vector<int> e[scx];
int ans[scx];

int find(int x) {
	while (fa[x] != x) {
		fa[x] = fa[fa[x]];
		x = fa[x];
	}
	return x;
}

void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y) return;

	if (rnk[x] < rnk[y]) swap(x, y);
	fa[y] = x;
	if (rnk[x] == rnk[y]) rnk[x]++;
}

int main() {
	cin >> n >> m;
	for (int i = 1; i <= n; i++) {
		fa[i] = i;
		rnk[i] = 0;
	}
	for (int i = 1; i <= m; i++) {
		int u, v;
		cin >> u >> v;
		++u; ++v;

		e[u].push_back(v);
		e[v].push_back(u);
	}

	cin >> k;
	for (int i = 1; i <= k; i++) {
		int p;
		cin >> p;
		++p;
		dead[p] = true;
		q[i] = p;
	}

	for (int u = 1; u <= n; u++) {
		if (dead[u]) continue;
		for (int v : e[u]) {
			if (dead[v]) continue;
			unite(u, v);
		}
	}
	int now = 0;
	for (int i = 1; i <= n; i++) {
		if (!dead[i] && find(i) == i) {
			now++;
		}
	}

	for (int i = k; i >= 1; i--) {
		ans[i] = now;
		int u = q[i];
		dead[u] = false;
		now++;
		for (int v : e[u]) {
			if (!dead[v] && find(u) != find(v)) {
				unite(u, v);
				now--;
			}
		}
	}

	cout << now << '\n';
	for (int i = 1; i <= k; i++) {
		cout << ans[i] << '\n';
	}

	return 0;
}

#include<bits/stdc++.h>
using namespace std;

const int scx=1e6+10;
string s;
int ans[scx];

vector<string> op1(string s){
	vector<string>res;
	for(int i=0;i<(int)s.size();i++){
		for(int j=0;j<(int)s.size();j++){
			if(s[i]==s[j])continue;
			string ns=s;
			swap(ns[i],ns[j]);
			res.push_back(ns);
		}
	}
	return res;
}

vector<string> op2(string s){
	vector<string>res;
	for(int i=0;i<(int)s.size();i++){
		string ns=s;
		ns.erase(i,1);
		res.push_back(ns);
	}
	return res;
}

vector<string> op3(string s){
	vector<string>res;
	for(int i=0;i<(int)s.size()-1;i++){
		for(int j=s[i]+1;j<s[i+1];j++){
			string ns=s;
			ns.insert(i+1,1,j);
			res.push_back(ns);
		}
	}
	return res;
}

int strtoi(string s){
	int res=0;
	for(auto ch:s){
		res=res*10+(ch-'0');
	}
	return res;
}

int main(){
	cin>>s;
	queue<pair<string,int> >q;
	q.push(make_pair(s,1));
	while(!q.empty()){
		string ns=q.front().first;
		int tmp=q.front().second;
		q.pop();
		if(ans[strtoi(ns)]){
			continue;
		}
		ans[strtoi(ns)]=tmp;
		//cout<<ns<<' '<<tmp<<'\n';
		for(auto nns:op1(ns)){
			q.push(make_pair(nns,tmp+1));
		}
		if(ns.size()>1){
			for(auto nns:op2(ns)){
				q.push(make_pair(nns,tmp+1));
			}
		}
		if(ns.size()<s.size()){
			for(auto nns:op3(ns)){
				q.push(make_pair(nns,tmp+1));
			}
		}
	}
	int m;
	cin>>m;
	while(m--){
		string q;
		cin>>q;
		if(q.size()>s.size()){
			cout<<"-1\n";
			continue;
		}
		int v=ans[strtoi(q)];
		if(!v){
			cout<<"-1\n";
		}else{
			cout<<v-1<<'\n';
		}
	}
	return 0;
}

