	int u,v,nt;
}edge[scx<<1];
void add(int u,int v){
	edge[++tot]={u,v,head[u]};
	head[u]=tot;
}

void dfs(int u,int fa){
	cout<<u<<' ';
	priority_queue<int,vector<int>,greater<int> >q;
	for(int i=head[u];i;i=edge[i].nt){
		int v=edge[i].v;
		if(fa==v)continue;
		q.push(v);
	}
	while(!q.empty()){
		int v=q.top();
		q.pop();
		dfs(v,u);
	}
}

