int n,a,b;
int k[scx];
int ans;
bool vis[scx];

int main(){
	cin>>n>>a>>b;
	for(int i=1;i<=n;i++){
		cin>>k[i];
	}
	ans=inf;
	queue<pair<int,int> >q;
	q.push(make_pair(a,0));
	while(!q.empty()){
		int layer=q.front().first;
		int nans=q.front().second;
		q.pop();
		if(layer<1||layer>n)continue;
		if(layer==b){
			ans=min(ans,nans);
			continue;
		}
		if(vis[layer])continue;
		vis[layer]=1;
		q.push(make_pair(layer+k[layer],nans+1));
		q.push(make_pair(layer-k[layer],nans+1));
	}
	if(ans==inf)cout<<"-1";
	else cout<<ans;
	return 0;
}

