long long s = 0;       // ✅ 改为 long long

int x_x(long long x) {
    int z = 1, y = n;
    while (z < y) {
        int p = z + (y - z) / 2;
        if (a[p] >= x) y = p;
        else z = p + 1;
    }
    return z;
}

int awa(long long x) {
    int z = 1, y = n;
    while (z < y) {
        int p = z + (y - z + 1) / 2;
        if (a[p] <= x) z = p;
        else y = p - 1;
    }
    return z;
}

