using namespace std;

int r, c;
int res = 0;
int walk[4][2] = {
	{-1, 0}, {1, 0}, {0, -1}, {0, 1}
};
int grid[N][N];
int mem[N][N];
// mem[i][j] --> 记录的是从(i, j)这个点出发的最长的满足条件的序列的长度

// DFS函数，实现：从(x, y)出发，最长的这个序列的长度
int dfs(int x, int y);
bool is_ok(int x, int y);   // 判断(x, y)这个点是否越界，如果没有越界就返回true，否则返回false
int main() {
	cin >> r >> c;
	for (int i = 1; i <= r; i++) {
		for (int j = 1; j <= c; j++) {
			cin >> grid[i][j];
		}
	}
	for (int i = 1; i <= r; i++) {
		for (int j = 1; j <= c; j++) {
			res = max(res, dfs(i, j));
		}
	}
	cout << res << endl;
	return 0;
}
int dfs(int x, int y) {
	if (mem[x][y]) {
		return mem[x][y];
	}
	int max_l = 1;   // max_l用来记录从当前的(x, y)出发的最长序列
	for (int i = 0; i < 4; i++) {
		int to_x = x + walk[i][0];
		int to_y = y + walk[i][1];
		if (grid[to_x][to_y] < grid[x][y] && is_ok(to_x, to_y)) {
			max_l = max(max_l, 1 + dfs(to_x, to_y));
		}
	}
	mem[x][y] = max_l;
	return max_l;
}

bool is_ok(int x, int y) {
	return (x >= 1 && x <= r && y >= 1 && y <= c);
}

