inline int tr(char x){
	if('0'<=x&&x<='9'){
		return x-'0';
	}
	if('a'<=x&&x<='z'){
		return x-'a'+10;
	}
	return x-'A'+36;
}

void add(string s){
	int u=0;
	for(auto ch:s){
		int idx=tr(ch);
		if(trie[u][idx]==0){
			trie[u][idx]= ++tot;
		}
		u=trie[u][idx];
		cnt[u]++;
	}
}

int query(string s){
	int u=0;
	for(auto ch:s){
		int idx=tr(ch);
		if(trie[u][idx]==0){
			return 0;
		}
		u=trie[u][idx];
	}
	return cnt[u];
}

