	{0,6,7,7,7,7,7,7,7,6},
	{0,6,6,6,6,6,6,6,6,6},
};
int f(int x,int y){
	return fs[x][y];
}

int f1(int x, int y) {
	if (x <= 3) {
		if (y <= 3) {
			return 1;
		} else if (y <= 6) {
			return 4;
		} else {
			return 7;
		}
	} else if (x <= 6) {
		if (y <= 3) {
			return 2;
		} else if (y <= 6) {
			return 5;
		} else {
			return 8;
		}
	} else {
		if (y <= 3) {
			return 3;
		} else if (y <= 6) {
			return 6;
		} else {
			return 9;
		}
	}
}

struct Point {
	int x, y, zone;
} kong[100];
int kongcnt = 0;
int cta[10] = {0};

bool cmp(const Point &a, const Point &b) {
	return cta[a.x] < cta[b.x];
}

int cur_sum = 0;

void dfs(int filled) {
	if (filled == kongcnt) {
		if (ans < cur_sum) ans = cur_sum;
		return;
	}
	int max_possible = cur_sum;
	for (int i = 0; i < kongcnt; i++) {
		if (a[kong[i].x][kong[i].y] == 0) {
			max_possible += f(kong[i].x, kong[i].y) * 9;
		}
	}
	if (max_possible <= ans) return;

	int best = -1, best_cnt = 10;
	for (int i = 0; i < kongcnt; i++) {
		if (a[kong[i].x][kong[i].y] == 0) {
			int cnt = 0;
			int x = kong[i].x, y = kong[i].y, z = kong[i].zone;
			for (int num = 1; num <= 9; num++) {
				if (!(h[x] & (1<<num)) && !(l[y] & (1<<num)) && !(k[z] & (1<<num)))
					cnt++;
			}
			if (cnt < best_cnt) {
				best_cnt = cnt;
				best = i;
				if (cnt == 0) break;
            }
		}
	}
	if (best == -1 || best_cnt == 0) return;

	int x = kong[best].x;
	int y = kong[best].y;
	int z = kong[best].zone;
	for (int num = 1; num <= 9; num++) {
		if (!(h[x] & (1<<num)) && !(l[y] & (1<<num)) && !(k[z] & (1<<num))) {
			a[x][y] = num;
			h[x] |= (1<<num);
			l[y] |= (1<<num);
			k[z] |= (1<<num);
			cur_sum += f(x,y) * num;
			dfs(filled + 1);
			cur_sum -= f(x,y) * num;
			h[x] &= ~(1<<num);
			l[y] &= ~(1<<num);
			k[z] &= ~(1<<num);
			a[x][y] = 0;
		}
	}
}

int main() {
	for (int i = 1; i <= 9; i++) {
		for (int j = 1; j <= 9; j++) {
			a[i][j]=read();
			if (a[i][j] == 0) {
				kong[kongcnt].x = i;
				kong[kongcnt].y = j;
				kong[kongcnt].zone = f1(i, j);
				cta[i]++;
				kongcnt++;
			} else {
				if ((h[i] & (1 << a[i][j])) || (l[j] & (1 << a[i][j])) || (k[f1(i, j)] & (1 << a[i][j]))) {
					cout << "-1";
					return 0;
				}
				h[i] |= (1 << a[i][j]);
				l[j] |= (1 << a[i][j]);
				k[f1(i, j)] |= (1 << a[i][j]);
				cur_sum += f(i,j) * a[i][j];
			}
		}
	}
	sort(kong, kong + kongcnt, cmp);
	dfs(0);
	printf("%d",ans);
	return 0;
}

