struct BigInt {
	vector<int> d;

	BigInt(long long x = 0) {
		if (x == 0) d.push_back(0);
		else {
			while (x) {
				d.push_back(x % 10);
				x /= 10;
			}
		}
	}

	// 乘以一个 int（非负）
	void multiply(int x) {
		if (x == 0) { d.clear(); d.push_back(0); return; }
		int carry = 0;
		for (int i = 0; i < (int)d.size(); i++) {
			long long cur = 1LL * d[i] * x + carry;
			d[i] = cur % 10;
			carry = cur / 10;
		}
		while (carry) {
			d.push_back(carry % 10);
			carry /= 10;
		}
		trim();
	}

	BigInt divide(int x) const {
		BigInt res;
		res.d.clear();
		long long rem = 0;
		for (int i = (int)d.size() - 1; i >= 0; i--) {
			rem = rem * 10 + d[i];
			res.d.push_back(rem / x);
			rem %= x;
		}
		reverse(res.d.begin(), res.d.end());
		res.trim();
		return res;
	}

	bool operator<(const BigInt& other) const {
		if (d.size() != other.d.size()) return d.size() < other.d.size();
		for (int i = (int)d.size() - 1; i >= 0; i--) {
			if (d[i] != other.d[i]) return d[i] < other.d[i];
		}
		return false;
	}

	bool operator>(const BigInt& other) const {
		return other < *this;
	}

	void trim() {
		while (d.size() > 1 && d.back() == 0) d.pop_back();
	}

	void print() const {
		for (int i = (int)d.size() - 1; i >= 0; i--) cout << d[i];
	}
};

