        f[1 << i][i] = dis(0, i + 1);

    for (int mask = 1; mask < tot; mask++)
        for (int i = 0; i < n; i++) {
            if (!(mask & (1 << i))) continue;
            if (f[mask][i] == inf) continue;
            for (int j = 0; j < n; j++) {
                if (mask & (1 << j)) continue;
                int nmask = mask | (1 << j);
                f[nmask][j] = min(f[nmask][j], f[mask][i] + dis(i + 1, j + 1));
            }
        }

    double ans = inf;
    for (int i = 0; i < n; i++)
        ans = min(ans, f[tot - 1][i]);

    printf("%.2f\n", ans);
    return 0;
}

