pair<int,int> _find(pair<int,int> a){
	if(fa[a.first][a.second]==a)return a;
	return fa[a.first][a.second]=_find(fa[a.first][a.second]);
}

void connect(pair<int,int>a,pair<int,int>b){
	a=_find(a),b=_find(b);
	if(a==b)return ;
	fa[a.first][a.second]=b;
	siz[b.first][b.second]+=siz[a.first][a.second];
}

