int f[2][65][21][21][21][21];

const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};

int dfs(int opt, int h, int r1, int c1, int r2, int c2) {
	if (h > 3 * n) return inf;
	if (r1 == r2 && c1 == c2) {
		if (opt == 1) return inf;
		else return 0;
	}
	if (f[opt][h][r1][c1][r2][c2] != 0) 
		return f[opt][h][r1][c1][r2][c2];
	int res;
	if (opt == 0) {
		res = 0;
		for (int i = 0; i < 4; i++) {
			int xx = r1 + dx[i];
			int yy = c1 + dy[i];
			if (xx < 1 || xx > n || yy < 1 || yy > n) continue;
			res = max(res, dfs(1, h + 1, xx, yy, r2, c2));
		}
	} else {
		res = inf;
		for (int i = 0; i < 4; i++) {
			int xx = r2 + dx[i];
			int yy = c2 + dy[i];
			if (xx >= 1 && xx <= n && yy >= 1 && yy <= n)
				res = min(res, dfs(0, h + 1, r1, c1, xx, yy));
			xx = r2 + 2 * dx[i];
			yy = c2 + 2 * dy[i];
			if (xx >= 1 && xx <= n && yy >= 1 && yy <= n)
				res = min(res, dfs(0, h + 1, r1, c1, xx, yy));
		}
	}

	return f[opt][h][r1][c1][r2][c2] = res + 1;
}

