	head[u] = tot;
}

int xhead[scx], xtot;
node xedge[scx << 2];
void xadd(int u, int v) {
	xedge[++xtot] = {v, xhead[u], 0};
	xhead[u] = xtot;
}

void dfs(int u, int fa) {
	dfn[u] = ++cnt;
	dep[u] = dep[fa] + 1;
	asn[u][0] = fa;
	for (int i = 1; i < LOG; i++) {
		asn[u][i] = asn[asn[u][i - 1]][i - 1];
	}
	for (int i = head[u]; i; i = edge[i].nt) {
		int v = edge[i].to;
		if (v == fa)
			continue;
		dfs(v, u);
	}
}

int lca(int u, int v) {
	if (dep[u] < dep[v])
		swap(u, v);
	if (u == v)
		return u;
	for (int i = LOG - 1; i >= 0; i--) {
		if (dep[asn[u][i]] >= dep[v])
			u = asn[u][i];
	}
	if (u == v)
		return u;
	for (int i = LOG - 1; i >= 0; i--) {
		if (asn[u][i] != asn[v][i]) {
			u = asn[u][i];
			v = asn[v][i];
		}
	}
	return asn[u][0];
}

void build(int k) {
	sort(key + 1, key + 1 + k, [&](int a, int b) {
		return dfn[a] < dfn[b];
	});
	k = unique(key + 1, key + 1 + k) - (key + 1);
	stk[top = 1] = 1;
	for (int i = 1; i <= k; i++) {
		int u = key[i];
		//if(u==1)continue;
		int l = lca(u, stk[top]);
		while (top > 1 && dep[stk[top - 1]] >= dep[l]) {
			xadd(stk[top - 1], stk[top]);
			top--;
		}
		if (stk[top] != l) {
			xadd(l, stk[top]);
			stk[top] = l;
		}
		stk[++top] = u;
	}
	while (top > 1) {
		xadd(stk[top - 1], stk[top]);
		top--;
	}
}

