	for (int i = head[u]; i; i = edge[i].nt) {
		int v = edge[i].to;
		if (v != fa) {
			min_edge[v] = min(min_edge[u], (long long)edge[i].val);
			dfs2(v, u);
		}
	}
}

void dfs3(int u, int fa) {
	dp[u] = 0;
	long long sum = 0;
	for (int i = xhead[u]; i; i = xedge[i].nt) {
		int v = xedge[i].to;
		if (v == fa)
			continue;
		dfs3(v, u);
		sum += dp[v];
	}
	if (iskey[u]) {
		dp[u] = min_edge[u];
	} else {
		dp[u] = min(min_edge[u], sum);
	}
	xhead[u] = 0;
}

int main() {
	cin >> n;
	min_edge[1] = 1e18;
	for (int i = 1; i < n; i++) {
		int u, v, w;
		cin >> u >> v >> w;
		add(u, v, w);
		add(v, u, w);
	}
