	dfs2(1, 0);
	cin >> m;
	while (m--) {
		int k;
		cin >> k;
		for (int j = 1; j <= k; j++) {
			cin >> key[j];
			iskey[key[j]] = true;
		}
		xtot = 0;
		build(k);
		dfs3(1, 0);
