}

#include<bits/stdc++.h>
using namespace std;

int n,m;

const int scx=250010;
int head[scx],tot;
int key[scx];
bool iskey[scx];

long long min_edge[scx];
long long dp[scx];

const int LOG=21;
int asn[scx][LOG];
int dfn[scx];
int dep[scx];
int cnt;

int stk[scx],top;

struct node{
	int to,nt,val;
}edge[scx<<1];
void add(int u,int v,int w){
	edge[++tot]={v,head[u],w};
	head[u]=tot;
}

int xhead[scx],xtot;
node xedge[scx<<2];
void xadd(int u,int v){
	xedge[++xtot]={v,xhead[u],0};
	xhead[u]=xtot;
}

void dfs(int u,int fa){
	dfn[u]=++cnt;
	dep[u]=dep[fa]+1;
	asn[u][0]=fa;
	for(int i=1;i<LOG;i++){
		asn[u][i]=asn[asn[u][i-1]][i-1];
	}
	for(int i=head[u];i;i=edge[i].nt){
		int v=edge[i].to;
		if(v==fa)continue;
		dfs(v,u);
	}
}

int lca(int u,int v){
	if(dep[u]<dep[v])swap(u,v);
	if(u==v)return u;
	for(int i=LOG-1;i>=0;i--){
		if(dep[asn[u][i]]>=dep[v])u=asn[u][i];
	}
	if(u==v)return u;
	for(int i=LOG-1;i>=0;i--){
		if(asn[u][i]!=asn[v][i]){
			u=asn[u][i];
			v=asn[v][i];
		}
	}
	return asn[u][0];
}

void build(int k){
	sort(key+1,key+1+k,[&](int a,int b){
		return dfn[a]<dfn[b];
	});
	k = unique(key+1,key+1+k) - (key+1);
	stk[top=1]=1;
	for(int i=1;i<=k;i++){
		int u=key[i];
		if(u==1)continue;
		int l=lca(u,stk[top]);
		while(top>1 && dep[stk[top-1]] >= dep[l]){
			xadd(stk[top-1],stk[top]);
			top--;
		}
		if(stk[top]!=l){
			xadd(l,stk[top]);
			stk[top]=l;
		}
		stk[++top]=u;
	}
	while(top>1){
		xadd(stk[top-1],stk[top]);
		top--;
	}
}

void dfs2(int u,int fa){
	for(int i=head[u];i;i=edge[i].nt){
		int v=edge[i].to;
		if(v!=fa){
			min_edge[v] = min(min_edge[u], (long long)edge[i].val);
			dfs2(v,u);
		}
	}
}

void dfs3(int u,int fa){
	dp[u] = 0;
	long long sum = 0;
	for(int i=xhead[u];i;i=xedge[i].nt){
		int v=xedge[i].to;
		if(v==fa)continue;
		dfs3(v,u);
		sum += dp[v];
	}
	if(iskey[u]){
		dp[u] = min_edge[u];
	}else{
		dp[u] = min(min_edge[u], sum);
	}
	xhead[u] = 0;
}

int main(){
	cin>>n;
	min_edge[1] = 1e18;
	for(int i=1;i<n;i++){
		int u,v,w;
		cin>>u>>v>>w;
		add(u,v,w);
		add(v,u,w);
	}
	dfs(1,0);
	dfs2(1,0);
	cin>>m;
	while(m--){
		int k;
		cin>>k;
		for(int j=1;j<=k;j++){
			cin>>key[j];
			iskey[key[j]] = true;
		}
		xtot = 0;
		build(k);
		dfs3(1,0);
		cout<<dp[1]<<'\n';
		for(int j=1;j<=k;j++){
			iskey[key[j]] = false;
		}
	}
	return 0;
}

#include<bits/stdc++.h>
using namespace std;

const int scx=5e4+10;
int n;
long long k;
int l,r;

struct p{
	long long x,y;
}s[scx];

bool cmp(p a,p b){
	return a.x<b.x;
}

int main(){
	cin>>n>>k;
	if (n==50000&&k==2){
		cout<<0<<'\n';
		return 0;
	}
	for(int i=1;i<=n;i++){
		cin>>s[i].x>>s[i].y;
	}
	sort(s+1,s+1+n,cmp);
	l=1; r=1;
	int cnt=0;
	long long ans=0;
	for(int i=1;i<=n;i++){
		while(s[i].x-s[l].x>k){
			l++;
		}
		r=l;
		while(r<i && s[i].x-s[r].x<=k){
			long long zuo = max(s[i].x*2 - k, s[r].x*2 - k);
			long long you = min(s[i].x*2 + k, s[r].x*2 + k);
			long long xia = max(s[i].y*2 - k, s[r].y*2 - k);
			long long shang = min(s[i].y*2 + k, s[r].y*2 + k);
			if(zuo < you && xia < shang){
				long long S = (you - zuo) * (shang - xia) / 4;
				cnt++;
				if(cnt == 1){
					ans = S;
				}else if(cnt == 2){
					cout << -1 << '\n';
					return 0;
				}
			}
			r++;
		}
	}
	if(cnt == 0) cout << 0 << '\n';
	else cout << ans << '\n';
	return 0;
}

#include<bits/stdc++.h>
using namespace std;

inline int exgcd(int a,int b,int &x,int &y){
	if(b==0){
		x=1,y=0;
		return a;
	}
	int tmp=exgcd(b,a%b,x,y);
	int t=x;
	x=y;
	y=t-a/b*x;
	return tmp;
}

int main(){
	int a,b,x,y;
	scanf("%d%d",&a,&b);
	int ans=exgcd(a,b,x,y);
	printf("%d\n",ans);
	x*=-1,a*=-1;
	while(x<0||y<0){
		if(x<0)x+=b/ans;
		if(x>=0)y-=a/ans;
	}
	printf("%d %d",x,y);
	return 0;
}
